const{chromium}=require('playwright');const assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch();try{for(const name of ['bass-b2b-adoption','saas-churn-vs-winrate','car-dealership-profit'])for(const width of[390,1280]){const p=await b.newPage({viewport:{width,height:width===390?844:800}});await p.goto('file://'+require('path').resolve(__dirname,'../../../projects',name,'explorer.html'));await p.waitForSelector('.tile');assert.equal(await p.locator('.quick-control input').count(),2,'two starting controls');const r=await p.locator('#quick-controls').boundingBox();assert.ok(r.y+r.height<= (width===390?844:800),name+' controls must fit the first screen: '+JSON.stringify(r));const original=await p.evaluate(()=>SDExplorer.params());const baseline=await p.evaluate(()=>SDExplorer.baselineParams());await p.locator('.quick-control input').first().focus();await p.keyboard.press('ArrowRight');await p.waitForTimeout(60);assert.notDeepEqual(await p.evaluate(()=>SDExplorer.params()),original);assert.deepEqual(await p.evaluate(()=>SDExplorer.baselineParams()),baseline);await p.locator('.quick-reset').first().click();await p.waitForTimeout(60);assert.deepEqual(await p.evaluate(()=>SDExplorer.params()),original);await p.close()}}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)})
